{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Tetrabenazine has very low mean oral systemic availability (0.049 ± 0.032) in patients, but this reflects extensive first-pass metabolism of a benzoquinolizine scaffold with different metabolic liabilities than the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Cepharanthine absolute oral bioavailability is 6–9% in humans, below the 20% threshold, but this large bisbenzylisoquinoline has poor solubility and extensive metabolism, unlike the smaller, well-absorbed galantamine scaffold.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Physostigmine has poor oral bioavailability, but its carbamate/indole structure and chemical instability are not representative of the query's benzofuran-azepane alkaloid system.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "MK-458 absolute oral bioavailability was 4.1% (range 3.3–6.0%) in patients, below threshold, but this is a different dopaminergic agonist with high first-pass metabolism and does not transfer to galantamine.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is galantamine, which has established high absolute oral bioavailability (~90%) in humans, well above the 20% threshold. The visible low-bioavailability records come from structurally and mechanistically distinct molecules and do not override this.",
  "evidence_gaps": [
    "No direct galantamine oral bioavailability record is present in the supplied evidence; the high-F conclusion relies on recognized galantamine pharmacokinetics.",
    "The visible records are all low-F comparators with limited structural transferability to the query.",
    "No human absolute F value for galantamine is provided among the experimental records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

